"$credentialInput = "protocol=https`nhost=github.com`n`n"
$output = $credentialInput | git credential fill
$token = ""
$username = ""
foreach ($line in ($output -split "`n")) {
    if ($line -match "^username=(.+)$") {
        $username = $matches[1].Trim()
    }
    if ($line -match "^password=(.+)$") {
        $token = $matches[1].Trim()
    }
}

Write-Output "Retrieved Username: $username"
if ($token -ne "") {
    Write-Output "Token found (Length: $($token.Length))"
    # Try calling GitHub API to create repository
    $headers = @{
        "Authorization" = "token $token"
        "User-Agent" = "Antigravity-Agent"
        "Accept" = "application/vnd.github.v3+json"
    }

    $body = @{
        name = "kreativpulse"
        description = "Refonte UI/UX moderne du site web de l'agence Kreativ'Pulse (Dakar, Sénégal) - Prototype interactif"
        private = $false
        has_issues = $true
        has_projects = $true
        has_wiki = $false
    } | ConvertTo-Json

    try {
        $response = Invoke-RestMethod -Uri "https://api.github.com/user/repos" -Method Post -Headers $headers -Body $body -ContentType "application/json"
        Write-Output "SUCCESS: Repository created at $($response.html_url)"
    } catch {
        Write-Output "API Call Error: $_"
        Write-Output "Response: $($_.Exception.Response)"
    }
} else {
    Write-Output "No token retrieved."
}
"

