"const https = require('https');
const fs = require('fs');

const urls = [
  'https://kreativpulse.net/',
  'https://kreativpulse.net/portfolio/',
  'https://kreativpulse.net/nos-services/',
  'https://kreativpulse.net/a-propos/',
  'https://kreativpulse.net/contact/'
];

function fetch(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

async function run() {
  const allImages = new Set();
  const allProjects = [];

  for (const url of urls) {
    try {
      const html = await fetch(url);
      const matches = html.match(/https?:\/\/kreativpulse\.net\/wp-content\/uploads\/[^"'\s<>]+\.(?:jpg|jpeg|png|webp)/gi) || [];
      matches.forEach(m => allImages.add(m));
      console.log(`URL ${url} -> ${matches.length} images`);

      // Let's also search for post links like /portfolio/..., or /project/..., or post titles
      const postLinks = html.match(/https?:\/\/kreativpulse\.net\/(?:portfolio|project|item|realisation)[^"'\s<>]+/gi) || [];
      if (postLinks.length > 0) {
        console.log(`Found post links on ${url}:`, Array.from(new Set(postLinks)));
      }
    } catch (err) {
      console.error(`Error on ${url}:`, err.message);
    }
  }

  const arr = Array.from(allImages);
  console.log(`\n=== Total unique images found: ${arr.length} ===`);

  const results = {
    total: arr.length,
    images: arr
  };

  fs.writeFileSync('C:/Users/hp/.gemini/antigravity-ide/brain/6002eba5-3c2b-4803-bc5e-c0002296233e/scratch/scraped_images.json', JSON.stringify(results, null, 2));
  console.log('Saved to scraped_images.json');
}

run();
"

