const sharp = require('sharp');
const fs = require('fs');

async function testTransparency(filePath, destPath, threshold = 245) {
  const img = sharp(filePath).ensureAlpha();
  const { data, info } = await img.raw().toBuffer({ resolveWithObject: true });

  // Create transparent buffer
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i+1], b = data[i+2];
    // Check if pixel is white / light gray
    if (r >= threshold && g >= threshold && b >= threshold) {
      data[i+3] = 0; // Transparent
    } else if (r >= threshold - 20 && g >= threshold - 20 && b >= threshold - 20) {
      // Soft antialiasing on edges
      const diff = 255 - Math.max(r, g, b);
      data[i+3] = Math.min(data[i+3], Math.round((diff / (255 - (threshold - 20))) * 255));
    }
  }

  await sharp(data, { raw: { width: info.width, height: info.height, channels: 4 } })
    .trim()
    .resize({ height: 80, fit: 'inside' })
    .png()
    .toFile(destPath);
