const sharp = require('sharp');

// Let's create a version for dark backgrounds where black/dark text is converted to crisp white/light
async function optimizeForDarkMode(src, dest) {
  const { data, info } = await sharp(src).raw().toBuffer({ resolveWithObject: true });
  for (let i = 0; i < data.length; i += 4) {
    const a = data[i+3];
    if (a > 30) {
      const r = data[i], g = data[i+1], b = data[i+2];
      // If it is dark text (r < 70, g < 70, b < 70)
      if (r < 75 && g < 75 && b < 75) {
        data[i] = 255;
        data[i+1] = 255;
        data[i+2] = 255;
      }
    }
  }
  await sharp(data, { raw: { width: info.width, height: info.height, channels: 4 } })
    .png()
    .toFile(dest);
  console.log('Created dark-mode optimized logo:', dest);
}

async function run() {
  await optimizeForDarkMode('assets/logos/partner-dpworld.png', 'assets/logos/partner-dpworld.png');
  await optimizeForDarkMode('assets/logos/partner-aner.png', 'assets/logos/partner-aner.png');
}
