const sharp = require('sharp');

async function makeTransparent(srcFile, destFile, threshold = 240, maxHeight = 70) {
  const img = sharp(srcFile).ensureAlpha();
  const { data, info } = await img.raw().toBuffer({ resolveWithObject: true });
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i+1], b = data[i+2];
    if (r >= threshold && g >= threshold && b >= threshold) {
      data[i+3] = 0;
    } else if (r >= threshold - 25 && g >= threshold - 25 && b >= threshold - 25) {
      const diff = 255 - Math.max(r, g, b);
      data[i+3] = Math.min(data[i+3], Math.round((diff / (255 - (threshold - 25))) * 255));
    }
  }
  await sharp(data, { raw: { width: info.width, height: info.height, channels: 4 } })
    .trim()
    .resize({ height: maxHeight, fit: 'inside' })
    .png()
    .toFile(destFile);
  console.log('Processed', destFile);
}

async function run() {
  await makeTransparent('assets/logos/site-logo-05.webp', 'assets/logos/partner-dpworld.png', 240, 60);
  await makeTransparent('assets/logos/site-logo-04.webp', 'assets/logos/partner-aner.png', 242, 60);
}
