"const fs = require('fs');

function parsePortfolio(filename) {
  const html = fs.readFileSync(filename, 'utf8');
  // Match articles, titles, headings, and images
  const items = [];

  // WordPress portfolio themes usually have post/portfolio items
  // Let's find headings like <h3> or <h2> or <h4> inside portfolio items
  const titleMatches = [...html.matchAll(/<(?:h2|h3|h4|h5)[^>]*class="[^"]*(?:title|entry-title|portfolio)[^"]*"[^>]*>([\s\S]*?)<\/(?:h2|h3|h4|h5)>/gi)];
  console.log(filename, 'title matches:', titleMatches.length);
  titleMatches.forEach(m => {
    const clean = m[1].replace(/<[^>]+>/g, '').trim();
    if (clean) items.push(clean);
  });

  // Also extract all links with /portfolio/ or /project/
  const links = [...html.matchAll(/href="(https?:\/\/kreativpulse\.net\/(?:portfolio|project|nos-realisations)\/[^"]+)"/gi)];
  const uniqueLinks = Array.from(new Set(links.map(l => l[1])));

  return { items, uniqueLinks };
